import { navigate } from "gatsby";
import React, { useCallback, useEffect, useState } from "react";
import type { Activity, Itinerary, ItineraryDay } from "../types";
import { getItineraryById } from "../../../sessionServices/itineraries/itinerariesService";
import { deleteDay, listDaysByItinerary } from "../../../sessionServices/itineraries/itineraryDaysService";
import { deleteActivity, listActivitiesByItinerary } from "../../../sessionServices/itineraries/activitiesService";
import { ItineraryDayForm } from "./ItineraryDayForm";
import { ActivityForm } from "./ActivityForm";
import { SupportNotePanel } from "./SupportNotePanel";
import { SharePanel } from "./SharePanel";
import { RxCaretDown, RxCaretUp } from "react-icons/rx";
import { FaMapLocationDot, FaCalendarDays } from "react-icons/fa6";
import { BsPeopleFill } from "react-icons/bs";
import { PiAirplaneTakeoffFill } from "react-icons/pi";



interface Props {
  itineraryId: string;
}

type DayWithId = ItineraryDay & { id: string };
type ActivityWithId = Activity & { id: string };
type ItineraryWithId = Itinerary & { id: string };

export function ItineraryDetail({ itineraryId }: Props) {
  const [itinerary, setItinerary] = useState<ItineraryWithId | null>(null);
  const [days, setDays] = useState<DayWithId[]>([]);
  const [activities, setActivities] = useState<ActivityWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [addingDay, setAddingDay] = useState(false);
  const [editingDay, setEditingDay] = useState<DayWithId | null>(null);
  const [addingActivityForDay, setAddingActivityForDay] = useState<string | null>(null);
  const [editingActivity, setEditingActivity] = useState<ActivityWithId | null>(null);
  const [expandedDays, setExpandedDays] = useState<Set<string>>(new Set());

  const load = useCallback(async () => {
    const [itData, daysData, actsData] = await Promise.all([
      getItineraryById(itineraryId),
      listDaysByItinerary(itineraryId),
      listActivitiesByItinerary(itineraryId),
    ]);
    setItinerary(itData);
    setDays([...daysData].sort((a, b) => (a.date as { toMillis: () => number }).toMillis() - (b.date as { toMillis: () => number }).toMillis()));
    setActivities(actsData);
    setExpandedDays(new Set(daysData.map((d) => d.id)));
    setLoading(false);
  }, [itineraryId]);

  useEffect(() => { load(); }, [load]);

  async function handleDeleteDay(day: DayWithId) {
    if (!confirm(`Delete Day ${day.dayNumber} – ${day.city}? All its activities will also be removed.`)) return;
    const dayActivities = activities.filter((a) => a.itineraryDayId === day.id);
    await Promise.all(dayActivities.map((a) => deleteActivity(a.id)));
    await deleteDay(day.id);
    load();
  }

  async function handleDeleteActivity(act: ActivityWithId) {
    if (!confirm(`Delete activity "${act.name}"?`)) return;
    await deleteActivity(act.id);
    load();
  }

  function toggleDay(id: string) {
    setExpandedDays((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <div className="h-6 w-6 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      </div>
    );
  }

  if (!itinerary) {
    return <p className="text-sm text-gray-500">Itinerary not found.</p>;
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-wrap items-start justify-between gap-4 rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <h2 className="text-lg font-semibold text-gray-900">{itinerary.title}</h2>
            <StatusBadge status={itinerary.status} />
          </div>
          <p className="text-sm text-gray-500">{itinerary.summary}</p>
          <div className="flex flex-wrap gap-4 pt-1 text-xs text-gray-500">
            <span className="flex gap-1"><FaMapLocationDot className="text-main text-lg self-center" /> {itinerary.destinationCities.join(", ") || "—"}</span>
            <span className="flex gap-1"><FaCalendarDays className="text-main text-lg self-center" /> {formatDate(itinerary.startDate)} – {formatDate(itinerary.endDate)}</span>
            <span className="flex gap-1"><BsPeopleFill className="text-main text-lg self-center" /> {itinerary.travelerCount} traveler{itinerary.travelerCount !== 1 ? "s" : ""}</span>
            {itinerary.tripType && <span className="flex gap-1"><PiAirplaneTakeoffFill className="text-main text-lg self-center" /> {itinerary.tripType}</span>}
          </div>
          {itinerary.internalNotes && (
            <p className="mt-2 rounded-lg bg-yellow-50 px-3 py-1.5 text-xs text-yellow-800">
              Internal note: {itinerary.internalNotes}
            </p>
          )}
        </div>
        <button
          onClick={() => navigate(`/admin/itineraries/${itineraryId}/edit`)}
          className="rounded-lg border border-gray-300 px-4 py-1.5 text-sm font-medium text-gray-700 transition hover:bg-gray-100"
        >
          Edit itinerary
        </button>
      </div>

      {/* Days */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold text-gray-700 uppercase tracking-wide">
            Days ({days.length})
          </h3>
          {!addingDay && !editingDay && (
            <button
              onClick={() => setAddingDay(true)}
              className="rounded-lg bg-gray-900 px-3 py-1.5 text-xs font-medium text-white transition hover:bg-gray-700"
            >
              + Add day
            </button>
          )}
        </div>

        {addingDay && (
          <ItineraryDayForm
            itineraryId={itineraryId}
            nextDayNumber={days.length + 1}
            onSaved={() => { setAddingDay(false); load(); }}
            onCancel={() => setAddingDay(false)}
          />
        )}

        {days.length === 0 && !addingDay && (
          <p className="text-sm text-gray-400">No days yet. Add the first day to begin building the itinerary.</p>
        )}

        {days.map((day, index) => {
          const dayNumber = index + 1;
          const dayActivities = activities
            .filter((a) => a.itineraryDayId === day.id)
            .sort((a, b) => (a.startTime ?? "").localeCompare(b.startTime ?? ""));
          const expanded = expandedDays.has(day.id);

          return (
            <div key={day.id} className="rounded-xl bg-white shadow-sm ring-1 ring-gray-200">
              {/* Day header */}
              <div className="flex items-center justify-between px-4 py-3">
                <button
                  onClick={() => toggleDay(day.id)}
                  className="flex items-center gap-2 text-left"
                >
                  <span className="flex h-6 w-6 items-center justify-center rounded-full bg-gray-900 text-xs font-bold text-white">
                    {dayNumber}
                  </span>
                  <div>
                    <span className="text-sm font-medium text-gray-900">
                      {day.city}
                      {day.title && ` — ${day.title}`}
                    </span>
                    <span className="ml-2 text-xs text-gray-400">{formatDate(day.date)}</span>
                  </div>
                  {expanded ? (<RxCaretUp  />) : (<RxCaretDown  />)}
                </button>
                <div className="flex gap-3">
                  <button
                    onClick={() => { setEditingDay(day); setAddingDay(false); }}
                    className="text-xs text-gray-400 underline hover:text-gray-700"
                  >Edit</button>
                  <button
                    onClick={() => handleDeleteDay(day)}
                    className="text-xs text-red-400 underline hover:text-red-600"
                  >Delete</button>
                </div>
              </div>

              {editingDay?.id === day.id && (
                <div className="px-4 pb-4">
                  <ItineraryDayForm
                    itineraryId={itineraryId}
                    nextDayNumber={day.dayNumber}
                    existing={day}
                    onSaved={() => { setEditingDay(null); load(); }}
                    onCancel={() => setEditingDay(null)}
                  />
                </div>
              )}

              {expanded && editingDay?.id !== day.id && (
                <div className="border-t border-gray-100 px-4 py-3 space-y-3">
                  {day.notes && (
                    <p className="text-xs text-gray-500 italic">{day.notes}</p>
                  )}

                  {/* Activities */}
                  {dayActivities.length > 0 && (
                    <div className="space-y-2">
                      {dayActivities.map((act) => (
                        <div key={act.id}>
                          {editingActivity?.id === act.id ? (
                            <ActivityForm
                              itineraryId={itineraryId}
                              itineraryDayId={day.id}
                              dayNumber={day.dayNumber}
                              city={day.city}
                              existing={act}
                              onSaved={() => { setEditingActivity(null); load(); }}
                              onCancel={() => setEditingActivity(null)}
                            />
                          ) : (
                            <div className="flex items-start justify-between rounded-lg bg-gray-50 px-3 py-2">
                              <div>
                                <div className="flex items-center gap-2">
                                  {act.startTime && (
                                    <span className="text-xs font-mono text-gray-400">{formatTime(act.startTime)}</span>
                                  )}
                                  <span className="text-sm font-medium text-gray-800">{act.name}</span>
                                  {act.category && (
                                    <span className="rounded-full bg-gray-200 px-1.5 py-0.5 text-xs text-gray-600">
                                      {act.category}
                                    </span>
                                  )}
                                  {act.durationMinutes && (
                                    <span className="text-xs text-gray-400">{formatDuration(act.durationMinutes)}</span>
                                  )}
                                </div>
                                <p className="mt-0.5 text-xs text-gray-500">{act.description}</p>
                                {act.location && (
                                  <p className="text-xs text-gray-400">📍 {act.location}</p>
                                )}
                                {(act.cost != null || act.price != null || (act.costBreakdown && act.costBreakdown.length > 0)) && (
                                  <div className="mt-1.5 flex flex-wrap items-center gap-2">
                                    {act.cost != null && (
                                      <span className="text-xs text-gray-500">Cost: <span className="font-medium text-gray-700">${act.cost.toFixed(2)}</span></span>
                                    )}
                                    {act.price != null && (
                                      <span className="text-xs text-gray-500">Price: <span className="font-medium text-gray-700">${act.price.toFixed(2)}</span></span>
                                    )}
                                    {act.costBreakdown && act.costBreakdown.length > 0 && (
                                      <div className="flex flex-wrap gap-1">
                                        {act.costBreakdown.map((tag) => (
                                          <span key={tag} className="rounded-full bg-blue-50 px-2 py-0.5 text-xs text-blue-600">
                                            {tag}
                                          </span>
                                        ))}
                                      </div>
                                    )}
                                  </div>
                                )}
                              </div>
                              <div className="ml-4 flex gap-2 shrink-0">
                                <button
                                  onClick={() => setEditingActivity(act)}
                                  className="text-xs text-gray-400 underline hover:text-gray-700"
                                >Edit</button>
                                <button
                                  onClick={() => handleDeleteActivity(act)}
                                  className="text-xs text-red-400 underline hover:text-red-600"
                                >Delete</button>
                              </div>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  )}

                  {addingActivityForDay === day.id ? (
                    <ActivityForm
                      itineraryId={itineraryId}
                      itineraryDayId={day.id}
                      dayNumber={day.dayNumber}
                      city={day.city}
                      onSaved={() => { setAddingActivityForDay(null); load(); }}
                      onCancel={() => setAddingActivityForDay(null)}
                    />
                  ) : (
                    <button
                      onClick={() => setAddingActivityForDay(day.id)}
                      className="text-xs text-gray-500 underline hover:text-gray-800"
                    >
                      + Add activity
                    </button>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Share + internal notes */}
      <div className="grid gap-6 lg:grid-cols-2">
        <div className="rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200">
          <SharePanel itineraryId={itineraryId} />
        </div>
        <div className="rounded-xl bg-white p-5 shadow-sm ring-1 ring-gray-200">
          <SupportNotePanel itineraryId={itineraryId} />
        </div>
      </div>
    </div>
  );
}

const STATUS_BADGE: Record<string, string> = {
  draft: "bg-gray-100 text-gray-600",
  in_review: "bg-yellow-100 text-yellow-700",
  approved: "bg-blue-100 text-blue-700",
  shared: "bg-green-100 text-green-700",
  in_follow_up: "bg-purple-100 text-purple-700",
  closed: "bg-red-100 text-red-600",
};

function StatusBadge({ status }: { status: string }) {
  return (
    <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-medium ${STATUS_BADGE[status] ?? "bg-gray-100 text-gray-600"}`}>
      {status.replace("_", " ")}
    </span>
  );
}

function formatDuration(minutes: number): string {
  if (minutes < 60) return `${minutes} min`;
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return m > 0 ? `${h}h ${m}min` : `${h}h`;
}

function formatTime(time: string | undefined): string {
  if (!time) return "";
  const [h, m] = time.split(":").map(Number);
  const period = h >= 12 ? "PM" : "AM";
  const hour = h % 12 || 12;
  return `${hour}:${String(m).padStart(2, "0")}${period}`;
}

function formatDate(ts: unknown): string {
  try {
    const date = (ts as { toDate: () => Date }).toDate();
    const weekday = date.toLocaleDateString("en-US", { weekday: "long" });
    const day = date.getDate();
    const month = date.toLocaleDateString("en-US", { month: "long" });
    const year = date.getFullYear();
    return `${weekday}, ${day} ${month} - ${year}`;
  } catch {
    return "—";
  }
}
