import React, { useState } from "react";
import type { Activity } from "../types";
import {
  createActivity,
  updateActivity,
} from "../../../sessionServices/itineraries/activitiesService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId: string;
  itineraryDayId: string;
  dayNumber: number;
  city: string;
  existing?: Activity & { id: string };
  onSaved: () => void;
  onCancel: () => void;
}

const EMPTY = {
  name: "",
  description: "",
  startTime: "",
  durationMinutes: "",
  category: "",
  location: "",
  observations: "",
  cost: "",
  price: "",
  costBreakdownInput: "",
};

export function ActivityForm({
  itineraryId,
  itineraryDayId,
  dayNumber,
  city,
  existing,
  onSaved,
  onCancel,
}: Props) {
  const { user } = useAuth();
  const isEditing = Boolean(existing);

  const [form, setForm] = useState({
    name: existing?.name ?? "",
    description: existing?.description ?? "",
    startTime: existing?.startTime ?? "",
    durationMinutes: existing?.durationMinutes ? String(existing.durationMinutes) : "",
    category: existing?.category ?? "",
    location: existing?.location ?? "",
    observations: existing?.observations ?? "",
    cost: existing?.cost ? String(existing.cost) : "",
    price: existing?.price ? String(existing.price) : "",
    costBreakdownInput: "",
  });
  const [costBreakdown, setCostBreakdown] = useState<string[]>(existing?.costBreakdown ?? []);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  function set(field: keyof typeof EMPTY, value: string) {
    setForm((prev) => ({ ...prev, [field]: value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    setError(null);
    setSaving(true);
    try {
      if (isEditing && existing) {
        await updateActivity(existing.id, {
          name: form.name,
          description: form.description,
          startTime: form.startTime || undefined,
          durationMinutes: form.durationMinutes ? Number(form.durationMinutes) : undefined,
          category: form.category || undefined,
          location: form.location || undefined,
          observations: form.observations || undefined,
          cost: form.cost ? Number(form.cost) : undefined,
          costBreakdown: costBreakdown.length ? costBreakdown : undefined,
          price: form.price ? Number(form.price) : undefined,
          updatedBy: user.uid,
        });
      } else {
        await createActivity({
          itineraryId,
          itineraryDayId,
          dayNumber,
          city,
          name: form.name,
          description: form.description,
          startTime: form.startTime || undefined,
          durationMinutes: form.durationMinutes ? Number(form.durationMinutes) : undefined,
          category: form.category || undefined,
          location: form.location || undefined,
          observations: form.observations || undefined,
          cost: form.cost ? Number(form.cost) : undefined,
          costBreakdown: costBreakdown.length ? costBreakdown : undefined,
          price: form.price ? Number(form.price) : undefined,
          createdBy: user.uid,
        });
      }
      onSaved();
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-3 rounded-xl bg-white p-4 ring-1 ring-gray-200">
      <p className="text-xs font-medium text-gray-500">
        {isEditing ? "Edit activity" : "New activity"}
      </p>
      <div className="grid gap-3 sm:grid-cols-2">
        <div className="sm:col-span-2">
          <label className="mb-1 block text-xs font-medium text-gray-600">Name *</label>
          <input
            type="text"
            required
            value={form.name}
            onChange={(e) => set("name", e.target.value)}
            className={inputClass}
          />
        </div>
        <div className="sm:col-span-2">
          <label className="mb-1 block text-xs font-medium text-gray-600">Description *</label>
          <textarea
            required
            rows={2}
            value={form.description}
            onChange={(e) => set("description", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Start time</label>
          <input
            type="time"
            value={form.startTime}
            onChange={(e) => set("startTime", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Duration (min)</label>
          <input
            type="number"
            min={0}
            value={form.durationMinutes}
            onChange={(e) => set("durationMinutes", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Category</label>
          <input
            type="text"
            placeholder="e.g. museum, food, transport"
            value={form.category}
            onChange={(e) => set("category", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Location</label>
          <input
            type="text"
            value={form.location}
            onChange={(e) => set("location", e.target.value)}
            className={inputClass}
          />
        </div>
        <div className="sm:col-span-2">
          <label className="mb-1 block text-xs font-medium text-gray-600">Observations</label>
          <input
            type="text"
            value={form.observations}
            onChange={(e) => set("observations", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Cost</label>
          <input
            type="number"
            min={0}
            step="0.01"
            placeholder="0.00"
            value={form.cost}
            onChange={(e) => set("cost", e.target.value)}
            className={inputClass}
          />
        </div>
        <div>
          <label className="mb-1 block text-xs font-medium text-gray-600">Price</label>
          <input
            type="number"
            min={0}
            step="0.01"
            placeholder="0.00"
            value={form.price}
            onChange={(e) => set("price", e.target.value)}
            className={inputClass}
          />
        </div>
        <div className="sm:col-span-2">
          <label className="mb-1 block text-xs font-medium text-gray-600">Cost breakdown</label>
          <div className="flex gap-2">
            <input
              type="text"
              placeholder="Add description and press Enter"
              value={form.costBreakdownInput}
              onChange={(e) => set("costBreakdownInput", e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  const val = form.costBreakdownInput.trim();
                  if (val && !costBreakdown.includes(val)) {
                    setCostBreakdown((prev) => [...prev, val]);
                    set("costBreakdownInput", "");
                  }
                }
              }}
              className={inputClass}
            />
          </div>
          {costBreakdown.length > 0 && (
            <div className="mt-2 flex flex-wrap gap-1.5">
              {costBreakdown.map((tag) => (
                <span key={tag} className="inline-flex items-center gap-1 rounded-full bg-gray-100 px-2.5 py-0.5 text-xs text-gray-700">
                  {tag}
                  <button
                    type="button"
                    onClick={() => setCostBreakdown((prev) => prev.filter((t) => t !== tag))}
                    className="text-gray-400 hover:text-gray-600"
                  >
                    ×
                  </button>
                </span>
              ))}
            </div>
          )}
        </div>
      </div>
      {error && <p className="text-xs text-red-600">{error}</p>}
      <div className="flex gap-2">
        <button
          type="submit"
          disabled={saving}
          className="rounded-lg bg-gray-900 px-4 py-1.5 text-xs font-medium text-white disabled:opacity-60"
        >
          {saving ? "Saving..." : "Save activity"}
        </button>
        <button
          type="button"
          onClick={onCancel}
          className="rounded-lg border border-gray-300 px-4 py-1.5 text-xs font-medium text-gray-600"
        >
          Cancel
        </button>
      </div>
    </form>
  );
}

const inputClass =
  "block w-full rounded-lg border border-gray-300 px-3 py-1.5 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800";
